var n=`1288-stoba`;var t=`world-1288`;var a=`CW`;var o=`central-america-caribbean`;var s=4;var r=155;var g={en:`Stobá`,ua:`Стоба`};var d={en:`Stobá is a dish from Aruba and Curaçao featuring beef chuck, yellow onion, garlic, tomato. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Стоба, страва кухні країни Аруба й Кюрасао з такими основними складниками: яловича лопатка, жовта цибуля, часник, помідор. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var l=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 13 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 13 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:13,i:[[`beef-chuck`,810,`g`],[`canola-oil`,45,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`yellow-onion`,170,`g`],[`garlic`,4,`clove`],[`tomato`,320,`g`],[`green-bell-pepper`,220,`g`]]},{en:`Add the braising liquid and seasonings, cover and cook gently for about 110 minutes until the meat is tender and safely cooked.`,ua:`Додайте рідину та приправи для тушкування, накрийте кришкою й готуйте на малому вогні приблизно 110 хвилин до м’якості та повної готовності м’яса.`,t:[`braising`],m:110,i:[[`beef-stock`,880,`ml`],[`ground-cumin`,5,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 20 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 20 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:20,i:[[`potato`,350,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`cilantro`,20,`g`]]}];var u={slug:n,id:t,country:`CW`,region:o,servings:4,minutes:155,title:g,text:d,steps:l};export{a as country,u as default,t as id,r as minutes,o as region,s as servings,n as slug,l as steps,d as text,g as title};